vector<vector<int>> threeSum(vector<int> a) {
    sort(a.begin(), a.end());
    vector<vector<int>> ans;
    int n = (int)a.size();
    for (int i = 0; i + 2 < n; ++i) {
        if (i && a[i] == a[i-1]) continue;
        if (a[i] > 0) break;
        int l = i + 1, r = n - 1;
        while (l < r) {
            long long s = 1LL * a[i] + a[l] + a[r];
            if (s < 0) ++l;
            else if (s > 0) --r;
            else {
                ans.push_back({a[i], a[l], a[r]});
                int x = a[l], y = a[r];
                while (l < r && a[l] == x) ++l;
                while (l < r && a[r] == y) --r;
            }
        }
    }
    return ans;
}

int minSubArrayLen(long long target, const vector<int>& a) {
    // 前提：target > 0，所有 a[i] > 0。
    long long sum = 0;
    int left = 0, ans = (int)a.size() + 1;
    for (int right = 0; right < (int)a.size(); ++right) {
        sum += a[right];
        while (sum >= target) {
            ans = min(ans, right - left + 1);
            sum -= a[left++];
        }
    }
    return ans > (int)a.size() ? 0 : ans;
}

long long subarraySum(const vector<int>& a, long long k) {
    unordered_map<long long, long long> freq;
    freq[0] = 1;
    long long pre = 0, ans = 0;
    for (int x : a) {
        pre += x;
        auto it = freq.find(pre - k);
        if (it != freq.end()) ans += it->second;
        ++freq[pre];
    }
    return ans;
}

vector<int> spiralOrder(const vector<vector<int>>& a) {
    if (a.empty() || a[0].empty()) return {};
    vector<int> ans;
    int top = 0, bottom = (int)a.size()-1;
    int left = 0, right = (int)a[0].size()-1;
    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; ++c) ans.push_back(a[top][c]);
        ++top;
        for (int r = top; r <= bottom; ++r) ans.push_back(a[r][right]);
        --right;
        if (top <= bottom) {
            for (int c = right; c >= left; --c) ans.push_back(a[bottom][c]);
            --bottom;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; --r) ans.push_back(a[r][left]);
            ++left;
        }
    }
    return ans;
}

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int v = 0, ListNode* p = nullptr) : val(v), next(p) {}
};
ListNode* mergeTwo(ListNode* a, ListNode* b) {
    ListNode dummy;
    ListNode* tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }
        else { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

struct ListNode {
    int val; ListNode* next;
    ListNode(int v = 0, ListNode* p = nullptr) : val(v), next(p) {}
};
ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* cur = head;
    while (cur) {
        ListNode* next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

struct ListNode {
    int val; ListNode* next;
    ListNode(int v = 0, ListNode* p = nullptr) : val(v), next(p) {}
};
ListNode* detectCycle(ListNode* head) {
    ListNode *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            ListNode* p = head;
            while (p != slow) { p = p->next; slow = slow->next; }
            return p;
        }
    }
    return nullptr;
}

struct Node {
