bool validRange(TreeNode* p, long long lo, long long hi) {
    if (!p) return true;
    if (p->val<=lo || p->val>=hi) return false;
    return validRange(p->left,lo,p->val)
        && validRange(p->right,p->val,hi);
}
bool isValidBST(TreeNode* root) {
    return validRange(root,LLONG_MIN,LLONG_MAX);
}

struct TreeNode {
    int val; TreeNode *left=nullptr, *right=nullptr;
    explicit TreeNode(int v):val(v){}
};
TreeNode* lca(TreeNode* root, TreeNode* p, TreeNode* q) {
    if (!root || root==p || root==q) return root;
    TreeNode* a=lca(root->left,p,q);
    TreeNode* b=lca(root->right,p,q);
    if (a && b) return root;
    return a ? a : b;
}

void siftDown(vector<int>& a, int i, int n) {
    while (2*i+1 < n) {
        int child=2*i+1;
        if (child+1<n && a[child+1]>a[child]) ++child;
        if (a[i]>=a[child]) break;
        swap(a[i],a[child]);
        i=child;
    }
}
void buildMaxHeap(vector<int>& a) {
    int n=(int)a.size();
    for (int i=n/2-1; i>=0; --i) siftDown(a,i,n);
}

int kthLargest(const vector<int>& a, int k) {
    if (k<=0 || k>(int)a.size()) throw invalid_argument("invalid k");
    priority_queue<int,vector<int>,greater<int>> heap;
    for (int x:a) {
        heap.push(x);
        if ((int)heap.size()>k) heap.pop();
    }
    return heap.top();
}

vector<int> mergeSorted(const vector<vector<int>>& a) {
    using Item=tuple<int,int,int>;
    priority_queue<Item,vector<Item>,greater<Item>> pq;
    for (int r=0;r<(int)a.size();++r)
        if (!a[r].empty()) pq.emplace(a[r][0],r,0);
    vector<int> ans;
    while (!pq.empty()) {
        auto [value,r,i]=pq.top(); pq.pop();
        ans.push_back(value);
        if (i+1<(int)a[r].size()) pq.emplace(a[r][i+1],r,i+1);
    }
    return ans;
}

class MedianFinder {
    priority_queue<int> lo;
    priority_queue<int,vector<int>,greater<int>> hi;
public:
    void addNum(int x) {
        if (lo.empty() || x<=lo.top()) lo.push(x);
        else hi.push(x);
        if (lo.size()>hi.size()+1) { hi.push(lo.top()); lo.pop(); }
        if (hi.size()>lo.size()) { lo.push(hi.top()); hi.pop(); }
    }
    double findMedian() const {
        if (lo.empty()) throw out_of_range("no data");
        if (lo.size()!=hi.size()) return lo.top();
        return ((long long)lo.top()+hi.top())/2.0;
    }
};

vector<vector<int>> subsets(const vector<int>& a) {
    vector<vector<int>> ans;
    vector<int> path;
    function<void(int)> dfs=[&](int start) {
        ans.push_back(path);
        for (int i=start;i<(int)a.size();++i) {
            path.push_back(a[i]);
            dfs(i+1);
            path.pop_back();
        }
    };
    dfs(0);
    return ans;
}

vector<vector<int>> permuteUnique(vector<int> a) {
    sort(a.begin(),a.end());
    vector<vector<int>> ans;
    vector<int> path;
    vector<bool> used(a.size(),false);
    function<void()> dfs=[&] {
        if (path.size()==a.size()) { ans.push_back(path); return; }
        for (int i=0;i<(int)a.size();++i) {
            if (used[i]) continue;
            if (i>0 && a[i]==a[i-1] && !used[i-1]) continue;
            used[i]=true; path.push_back(a[i]);
            dfs();
            path.pop_back(); used[i]=false;
        }
    };
    dfs();
    return ans;
}

vector<string> generateParenthesis(int n) {
    if (n<0) return {};
    vector<string> ans;
    string path;
    function<void(int,int)> dfs=[&](int left,int right) {
        if (right==n) { ans.push_back(path); return; }
        if (left<n) {
            path.push_back('('); dfs(left+1,right); path.pop_back();
        }
        if (right<left) {
            path.push_back(')'); dfs(left,right+1); path.pop_back();
        }
    };
    dfs(0,0);
    return ans;
}

int coinChangeMemo(const vector<int>& coins, int amount) {
    if (amount<0) return -1;
    const int INF=INT_MAX/2;
    vector<int> memo(amount+1,-1);
    function<int(int)> dfs=[&](int rem) {
        if (rem==0) return 0;
        if (memo[rem]!=-1) return memo[rem];
        int best=INF;
        for (int c:coins) {
            if (c<=0) throw invalid_argument("positive coins required");
            if (c<=rem) best=min(best,1+dfs(rem-c));
        }
        return memo[rem]=best;
    };
    int ans=dfs(amount);
    return ans==INF ? -1 : ans;
}

vector<int> bfsDistances(const vector<vector<int>>& g, int source) {
    int n=(int)g.size();
    if (source<0 || source>=n) throw out_of_range("source");
    vector<int> dist(n,-1);
    queue<int> q;
    dist[source]=0; q.push(source);
    while (!q.empty()) {
        int u=q.front(); q.pop();
        for (int v:g[u]) {
            if (dist[v]!=-1) continue;
            dist[v]=dist[u]+1;
            q.push(v);
        }
    }
    return dist;
}

vector<int> topoSort(const vector<vector<int>>& g) {
    int n=(int)g.size();
    vector<int> degree(n,0), order;
    for (const auto& edges:g) for (int v:edges) ++degree[v];
    queue<int> q;
    for (int u=0;u<n;++u) if (degree[u]==0) q.push(u);
    while (!q.empty()) {
        int u=q.front(); q.pop(); order.push_back(u);
        for (int v:g[u]) if (--degree[v]==0) q.push(v);
    }
    if ((int)order.size()!=n) return {}; // 非空图时，空结果表示有环
    return order;
}

vector<long long> dijkstra(
    const vector<vector<pair<int,int>>>& g, int source) {
    const long long INF=LLONG_MAX/4;
    if (source<0 || source>=(int)g.size()) throw out_of_range("source");
    vector<long long> dist(g.size(),INF);
    using State=pair<long long,int>;
    priority_queue<State,vector<State>,greater<State>> pq;
    dist[source]=0; pq.push({0,source});
    while (!pq.empty()) {
        auto [d,u]=pq.top(); pq.pop();
        if (d!=dist[u]) continue;
        for (auto [v,w]:g[u]) {
            if (w<0) throw invalid_argument("negative edge");
            if (d+w<dist[v]) {
                dist[v]=d+w;
                pq.push({dist[v],v});
            }
        }
    }
    return dist;
}

void floyd(vector<vector<long long>>& d) {
    const long long INF=LLONG_MAX/4;
    int n=(int)d.size();
    for (int k=0;k<n;++k)
        for (int i=0;i<n;++i) {
            if (d[i][k]==INF) continue;
            for (int j=0;j<n;++j) {
                if (d[k][j]==INF) continue;
                d[i][j]=min(d[i][j],d[i][k]+d[k][j]);
            }
        }
    // 如有 d[i][i] < 0，则存在负环。
}

struct DSU {
    vector<int> p,sz;
    explicit DSU(int n):p(n),sz(n,1){ iota(p.begin(),p.end(),0); }
    int find(int x){ return p[x]==x ? x : p[x]=find(p[x]); }
    bool unite(int a,int b){
        a=find(a); b=find(b);
        if(a==b) return false;
        if(sz[a]<sz[b]) swap(a,b);
        p[b]=a; sz[a]+=sz[b]; return true;
    }
};
optional<long long> kruskal(int n, vector<tuple<int,int,int>> edges) {
    // 每条边为 (权重,u,v)，无向图；节点编号 0..n-1。
    if(n<=1) return 0LL;
    sort(edges.begin(),edges.end());
    DSU dsu(n);
    long long sum=0; int used=0;
    for(auto [w,u,v]:edges)
        if(dsu.unite(u,v)){
            sum+=w;
            if(++used==n-1) return sum;
        }
    return nullopt;
}

int maxNonOverlapping(vector<pair<int,int>> intervals) {
    sort(intervals.begin(),intervals.end(),[](auto a,auto b){
        return a.second<b.second;
    });
    long long end=LLONG_MIN;
    int count=0;
    for(auto [l,r]:intervals){
        if(l>=end){ ++count; end=r; }
    }
    return count;
}

int minJumps(const vector<int>& a) {
    int n=(int)a.size();
    if(n<=1) return 0;
    long long far=0,end=0;
    int steps=0;
    for(int i=0;i<n-1;++i){
        if(i>far) return -1;
        far=max(far,(long long)i+a[i]);
        if(i==end){
            if(far<=i) return -1;
            ++steps; end=far;
            if(end>=n-1) return steps;
        }
    }
    return -1;
}

long long minMergeCost(const vector<int>& weights) {
    priority_queue<long long,vector<long long>,greater<long long>> pq;
    for(int x:weights){
        if(x<0) throw invalid_argument("nonnegative weights required");
        pq.push(x);
    }
    long long cost=0;
    while(pq.size()>1){
        long long a=pq.top(); pq.pop();
        long long b=pq.top(); pq.pop();
        cost+=a+b; pq.push(a+b);
    }
    return cost;
}

long long maxProfitUnlimited(const vector<int>& prices) {
    long long profit=0;
    for(int i=1;i<(int)prices.size();++i)
        profit+=max(0LL,(long long)prices[i]-prices[i-1]);
    return profit;
}

long long maxSubArray(const vector<int>& a) {
    if(a.empty()) throw invalid_argument("nonempty array required");
    long long endHere=a[0],best=a[0];
    for(int i=1;i<(int)a.size();++i){
        endHere=max((long long)a[i],endHere+a[i]);
        best=max(best,endHere);
    }
    return best;
}

long long knapsack01(const vector<int>& weight,
                     const vector<int>& value,int capacity) {
    if(capacity<0 || weight.size()!=value.size())
        throw invalid_argument("invalid input");
    vector<long long> dp(capacity+1,0);
    for(int i=0;i<(int)weight.size();++i){
        if(weight[i]<=0) throw invalid_argument("positive weights required");
        for(int c=capacity;c>=weight[i];--c)
            dp[c]=max(dp[c],dp[c-weight[i]]+value[i]);
    }
    return dp[capacity];
}

long long coinCombinations(const vector<int>& coins,int amount) {
    if(amount<0) return 0;
    vector<long long> dp(amount+1,0);
    dp[0]=1;
    for(int c:coins){
        if(c<=0) throw invalid_argument("positive distinct coins required");
        for(int s=c;s<=amount;++s) dp[s]+=dp[s-c];
    }
    return dp[amount];
}

int longestCommonSubsequence(const string& a,const string& b) {
    int n=(int)a.size(),m=(int)b.size();
    vector<vector<int>> dp(n+1,vector<int>(m+1,0));
    for(int i=1;i<=n;++i)
        for(int j=1;j<=m;++j)
            if(a[i-1]==b[j-1]) dp[i][j]=dp[i-1][j-1]+1;
            else dp[i][j]=max(dp[i-1][j],dp[i][j-1]);
    return dp[n][m];
}

int longestPalindromeSubseq(const string& s) {
    int n=(int)s.size();
    if(n==0) return 0;
    vector<vector<int>> dp(n,vector<int>(n,0));
    for(int i=0;i<n;++i) dp[i][i]=1;
    for(int len=2;len<=n;++len)
        for(int l=0;l+len<=n;++l){
            int r=l+len-1;
            if(s[l]==s[r]) dp[l][r]=2+(len==2 ? 0 : dp[l+1][r-1]);
            else dp[l][r]=max(dp[l+1][r],dp[l][r-1]);
        }
    return dp[0][n-1];
}

struct TreeNode {
    int val; TreeNode *left=nullptr,*right=nullptr;
    explicit TreeNode(int v):val(v){}
};
pair<long long,long long> robState(TreeNode* p) {
    if(!p) return {0,0}; // {skip,take}
    auto [ls,lt]=robState(p->left);
    auto [rs,rt]=robState(p->right);
    long long skip=max(ls,lt)+max(rs,rt);
    long long take=p->val+ls+rs;
    return {skip,take};
}
long long robTree(TreeNode* root) {
    auto [skip,take]=robState(root);
    return max(skip,take);
}

class UnionFind {
    vector<int> parent,sz;
    int components;
public:
    explicit UnionFind(int n):parent(n),sz(n,1),components(n) {
        iota(parent.begin(),parent.end(),0);
    }
    int find(int x) {
        if(parent[x]!=x) parent[x]=find(parent[x]);
        return parent[x];
    }
    bool unite(int a,int b) {
        a=find(a); b=find(b);
        if(a==b) return false;
        if(sz[a]<sz[b]) swap(a,b);
        parent[b]=a; sz[a]+=sz[b]; --components;
        return true;
    }
    int count() const { return components; }
};

class Trie {
    struct Node {
        array<int,26> next;
        bool terminal=false;
        Node(){ next.fill(-1); }
    };
    vector<Node> nodes{Node{}};
    static int letter(char c) {
        if(c<'a'||c>'z') throw invalid_argument("lowercase a-z only");
        return c-'a';
    }
    int walk(const string& s) const {
        int u=0;
        for(char c:s){
            int v=nodes[u].next[letter(c)];
            if(v==-1) return -1;
            u=v;
        }
        return u;
    }
public:
    void insert(const string& s){
        int u=0;
        for(char c:s){
            int k=letter(c);
            if(nodes[u].next[k]==-1){
                int v=(int)nodes.size();
                nodes.emplace_back();
                nodes[u].next[k]=v;
            }
            u=nodes[u].next[k];
        }
        nodes[u].terminal=true;
    }
    bool search(const string& s) const {
        int u=walk(s); return u!=-1 && nodes[u].terminal;
    }
    bool startsWith(const string& s) const { return walk(s)!=-1; }
};

class Fenwick {
    int n;
    vector<long long> bit;
public:
    explicit Fenwick(int size):n(size),bit(size+1,0){}
    void add(int i,long long delta){
        if(i<1||i>n) throw out_of_range("index");
        for(;i<=n;i+=i&-i) bit[i]+=delta;
    }
    long long prefix(int i) const {
        if(i<0||i>n) throw out_of_range("index");
        long long ans=0;
        for(;i>0;i-=i&-i) ans+=bit[i];
        return ans;
    }
    long long rangeSum(int l,int r) const {
        if(l<1||r>n||l>r) throw out_of_range("range");
        return prefix(r)-prefix(l-1);
    }
};

class SegmentTree {
    int n;
    vector<long long> tree;
public:
    explicit SegmentTree(const vector<int>& a):n((int)a.size()),tree(2*a.size(),0){
        for(int i=0;i<n;++i) tree[n+i]=a[i];
        for(int i=n-1;i>0;--i) tree[i]=tree[i*2]+tree[i*2+1];
    }
    void setValue(int p,long long value){
        if(p<0||p>=n) throw out_of_range("index");
        p+=n; tree[p]=value;
        for(p/=2;p>0;p/=2) tree[p]=tree[p*2]+tree[p*2+1];
    }
    long long query(int l,int r) const {
        if(l<0||r<l||r>n) throw out_of_range("range");
        long long ans=0;
        for(l+=n,r+=n;l<r;l/=2,r/=2){
            if(l&1) ans+=tree[l++];
            if(r&1) ans+=tree[--r];
        }
        return ans;
    }
};

class LRUCache {
    size_t cap;
    list<pair<int,int>> order;
    unordered_map<int,list<pair<int,int>>::iterator> pos;
public:
    explicit LRUCache(int capacity):cap(max(0,capacity)){}
    LRUCache(const LRUCache&)=delete;
    LRUCache& operator=(const LRUCache&)=delete;
    int get(int key){
        auto it=pos.find(key);
        if(it==pos.end()) return -1;
        order.splice(order.begin(),order,it->second);
        return it->second->second;
    }
    void put(int key,int value){
        auto it=pos.find(key);
        if(it!=pos.end()){
            it->second->second=value;
            order.splice(order.begin(),order,it->second);
            return;
        }
        if(cap==0) return;
        order.emplace_front(key,value);
        pos[key]=order.begin();
        if(order.size()>cap){
            pos.erase(order.back().first);
            order.pop_back();
        }
    }
};

int minMeetingRooms(const vector<pair<int,int>>& meetings){
    vector<pair<int,int>> events;
    for(auto [l,r]:meetings){
        if(l>r) throw invalid_argument("invalid interval");
        if(l==r) continue;
        events.push_back({l,1});
        events.push_back({r,-1});
    }
    sort(events.begin(),events.end());
    int active=0,best=0;
    for(auto [time,delta]:events){
        active+=delta;
        best=max(best,active);
    }
    return best;
}

class RandomizedSet {
    vector<int> data;
    unordered_map<int,int> index;
    mt19937 rng{random_device{}()};
public:
    bool insert(int x){
        if(index.count(x)) return false;
        index[x]=(int)data.size(); data.push_back(x); return true;
    }
    bool remove(int x){
        auto it=index.find(x);
        if(it==index.end()) return false;
        int i=it->second,last=data.back();
        data[i]=last; index[last]=i;
        data.pop_back(); index.erase(x); return true;
    }
    int getRandom(){
        if(data.empty()) throw out_of_range("empty set");
        uniform_int_distribution<int> pick(0,(int)data.size()-1);
        return data[pick(rng)];
    }
};

vector<int> primesUpTo(int n){
    if(n<2) return {};
    vector<bool> prime(n+1,true);
    prime[0]=prime[1]=false;
    for(int p=2;p<=n/p;++p)
        if(prime[p])
            for(long long x=1LL*p*p;x<=n;x+=p) prime[(size_t)x]=false;
    vector<int> ans;
    for(int x=2;x<=n;++x) if(prime[x]) ans.push_back(x);
    return ans;
}
long long gcdNonnegative(long long a,long long b){
    // 前提：a,b >= 0；约定 gcd(0,0)=0。
    while(b){ long long r=a%b; a=b; b=r; }
    return a;
}

pair<int,int> twoSumSorted(const vector<int>& a,long long target){
    int l=0,r=(int)a.size()-1;
    while(l<r){
        long long sum=(long long)a[l]+a[r];
        if(sum==target) return {l,r};
        if(sum<target) ++l;
        else --r;
    }
    return {-1,-1};
}

long long kadane(const vector<int>& a){
    if(a.empty()) throw invalid_argument("nonempty required");
    long long cur=a[0],ans=a[0];
    for(int i=1;i<(int)a.size();++i){
        cur=max((long long)a[i],cur+a[i]); ans=max(ans,cur);
    }
    return ans;
}
int main(){
    assert(kadane({-5,-2,-9})==-2);
    assert(kadane({0})==0);
    assert(kadane({4,-1,2,1})==6);
    assert(kadane({-2,1,-3,4,-1,2,1,-5,4})==6);
    cout<<"all checks passed\n";
}

